begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.crid(n integer) returns uuid language sql immutable as $$select ('cf900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,is_anonymous) select pg_temp.crid(n),false from generate_series(1,3)n;
insert into auth.sessions(id,user_id) select pg_temp.crid(n+100),pg_temp.crid(n) from generate_series(1,3)n;
insert into public.organizations(id,name,slug) values(pg_temp.crid(10),'Charging RPC tests','charging-rpc-tests');
insert into public.tenants(id,organization_id,name,slug) values(pg_temp.crid(20),pg_temp.crid(10),'A','charging-rpc-a'),(pg_temp.crid(21),pg_temp.crid(10),'B','charging-rpc-b');
insert into public.memberships(id,tenant_id,user_id) values(pg_temp.crid(30),pg_temp.crid(20),pg_temp.crid(1)),(pg_temp.crid(31),pg_temp.crid(21),pg_temp.crid(2));
insert into public.membership_roles(tenant_id,membership_id,role_id)
 select m.tenant_id,m.id,r.id from public.memberships m join public.roles r on r.tenant_id=m.tenant_id and r.role_key='tenant_admin' where m.id in(pg_temp.crid(30),pg_temp.crid(31));
insert into public.customers(id,tenant_id,customer_type,display_name) values(pg_temp.crid(40),pg_temp.crid(20),'person','A'),(pg_temp.crid(41),pg_temp.crid(21),'person','B');
insert into public.sites(id,tenant_id,customer_id,name) values(pg_temp.crid(50),pg_temp.crid(20),pg_temp.crid(40),'A'),(pg_temp.crid(51),pg_temp.crid(21),pg_temp.crid(41),'B');
insert into public.assets(id,tenant_id,site_id,customer_id,asset_type,display_name) values(pg_temp.crid(60),pg_temp.crid(20),pg_temp.crid(50),pg_temp.crid(40),'ev','A car'),(pg_temp.crid(61),pg_temp.crid(21),pg_temp.crid(51),pg_temp.crid(41),'ev','B car');
insert into public.platform_memberships(id,user_id) values(pg_temp.crid(70),pg_temp.crid(3));
insert into public.platform_membership_roles(platform_membership_id,role_id) select pg_temp.crid(70),id from public.roles where role_key='platform_admin' and scope_type='platform';
select ok(not has_function_privilege('anon','public.flexexa_charging_inventory(uuid)','execute'),'anonymous cannot read inventory');
select ok(not has_function_privilege('anon','public.flexexa_platform_charging_inventory(uuid)','execute'),'anonymous cannot aggregate');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.crid(1),'session_id',pg_temp.crid(101),'role','authenticated','aal','aal1')::text,true);
select is(public.flexexa_charging_inventory(pg_temp.crid(20))->'assets'->0->>'label','A car','A gets own real inventory');
select is(jsonb_array_length(public.flexexa_charging_inventory(pg_temp.crid(20))->'assets'),1,'foreign asset excluded');
select is(jsonb_array_length(public.flexexa_charging_companies()),1,'company selection is scoped');
select throws_ok($$select public.flexexa_charging_inventory(pg_temp.crid(21))$$,'42501','PERMISSION_DENIED','A cannot select B');
select throws_ok($$select public.flexexa_platform_charging_inventory(pg_temp.crid(900))$$,'42501','PERMISSION_DENIED','company cannot aggregate');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.crid(3),'session_id',pg_temp.crid(103),'role','authenticated','aal','aal1')::text,true);
select throws_ok($$select public.flexexa_platform_charging_inventory(pg_temp.crid(900))$$,'42501','PERMISSION_DENIED','platform requires MFA');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.crid(3),'session_id',pg_temp.crid(103),'role','authenticated','aal','aal2')::text,true);
select is(jsonb_array_length(public.flexexa_platform_charging_inventory(pg_temp.crid(900))->'companies'),2,'MFA admin aggregates both tenants');
reset role;
select is((select count(*)::integer from public.audit_events where action='platform_charging_inventory'),1,'authorized platform read creates canonical audit');
update auth.sessions set not_after=clock_timestamp()-interval '1 minute' where id=pg_temp.crid(101);
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.crid(1),'session_id',pg_temp.crid(101),'role','authenticated','aal','aal1')::text,true);
select throws_ok($$select public.flexexa_charging_inventory(pg_temp.crid(20))$$,'42501','PERMISSION_DENIED','expired session rejected');
select * from finish();
rollback;
